import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.when;

public class DatasetUtilities_iterateDomainBounds_TriageGen1Test {

    @Mock
    private XYDataset mockXYDataset;

    @Mock
    private IntervalXYDataset mockIntervalXYDataset;

    public DatasetUtilities_iterateDomainBounds_TriageGen1Test() {
        MockitoAnnotations.openMocks(this);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testIterateDomainBounds_NullDataset() {
        DatasetUtilities.iterateDomainBounds(null, false);
    }

    @Test
    public void testIterateDomainBounds_StandardXYDataset_NormalValues() {
        when(mockXYDataset.getSeriesCount()).thenReturn(1);
        when(mockXYDataset.getItemCount(0)).thenReturn(2);
        when(mockXYDataset.getXValue(0, 0)).thenReturn(10.0);
        when(mockXYDataset.getXValue(0, 1)).thenReturn(20.0);

        Range result = DatasetUtilities.iterateDomainBounds(mockXYDataset, false);

        assertEquals(10.0, result.getLower(), 1e-9);
        assertEquals(20.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testIterateDomainBounds_StandardXYDataset_WithNaN() {
        when(mockXYDataset.getSeriesCount()).thenReturn(1);
        when(mockXYDataset.getItemCount(0)).thenReturn(2);
        when(mockXYDataset.getXValue(0, 0)).thenReturn(Double.NaN);
        when(mockXYDataset.getXValue(0, 1)).thenReturn(5.0);

        Range result = DatasetUtilities.iterateDomainBounds(mockXYDataset, false);

        assertEquals(5.0, result.getLower(), 1e-9);
        assertEquals(5.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testIterateDomainBounds_StandardXYDataset_Empty() {
        when(mockXYDataset.getSeriesCount()).thenReturn(0);

        Range result = DatasetUtilities.iterateDomainBounds(mockXYDataset, false);

        assertNull(result);
    }

    @Test
    public void testIterateDomainBounds_IntervalXYDataset_IncludeInterval_True() {
        // When includeInterval is true and it's an IntervalXYDataset
        // Logic checks: XValue, StartXValue, EndXValue
        when(mockIntervalXYDataset.getSeriesCount()).thenReturn(1);
        when(mockIntervalXYDataset.getItemCount(0)).thenReturn(1);

        // Item 0: X=5, Start=2, End=8
        when(mockIntervalXYDataset.getXValue(0, 0)).thenReturn(5.0);
        when(mockIntervalXYDataset.getStartXValue(0, 0)).thenReturn(2.0);
        when(mockIntervalXYDataset.getEndXValue(0, 0)).thenReturn(8.0);

        Range result = DatasetUtilities.iterateDomainBounds(mockIntervalXYDataset, true);

        assertEquals(2.0, result.getLower(), 1e-9);
        assertEquals(8.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testIterateDomainBounds_IntervalXYDataset_IncludeInterval_True_WithNaN() {
        when(mockIntervalXYDataset.getSeriesCount()).thenReturn(1);
        when(mockIntervalXYDataset.getItemCount(0)).thenReturn(1);

        // Item 0: X=NaN, Start=NaN, End=10.0
        when(mockIntervalXYDataset.getXValue(0, 0)).thenReturn(Double.NaN);
        when(mockIntervalXYDataset.getStartXValue(0, 0)).thenReturn(Double.NaN);
        when(mockIntervalXYDataset.getEndXValue(0, 0)).thenReturn(10.0);

        Range result = DatasetUtilities.iterateDomainBounds(mockIntervalXYDataset, true);

        assertEquals(10.0, result.getLower(), 1e-9);
        assertEquals(10.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testIterateDomainBounds_IntervalXYDataset_IncludeInterval_False() {
        // If includeInterval is false, it falls into the 'else' block and treats it as standard XYDataset
        when(mockIntervalXYDataset.getSeriesCount()).thenReturn(1);
        when(mockIntervalXYDataset.getItemCount(0)).thenReturn(1);
        when(mockIntervalXYDataset.getXValue(0, 0)).thenReturn(15.0);

        // Note: Even though it's an IntervalXYDataset, because includeInterval is false, 
        // it uses the standard XYDataset loop which only calls getXValue.
        Range result = DatasetUtilities.iterateDomainBounds(mockIntervalXYDataset, false);

        assertEquals(15.0, result.getLower(), 1e-9);
        assertEquals(15.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testIterateDomainBounds_StandardXYDataset_MixedSeries() {
        when(mockXYDataset.getSeriesCount()).thenReturn(2);
        when(mockXYDataset.getItemCount(0)).thenReturn(1);
        when(mockXYDataset.getItemCount(1)).thenReturn(1);
        when(mockXYDataset.getXValue(0, 0)).thenReturn(1.0);
        when(mockXYDataset.getXValue(1, 0)).thenReturn(100.0);

        Range result = DatasetUtilities.iterateDomainBounds(mockXYDataset, false);

        assertEquals(1.0, result.getLower(), 1e-9);
        assertEquals(100.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testIterateDomainBounds_AllNaN() {
        when(mockXYDataset.getSeriesCount()).thenReturn(1);
        when(mockXYDataset.getItemCount(0)).thenReturn(1);
        when(mockXYDataset.getXValue(0, 0)).thenReturn(Double.NaN);

        Range result = DatasetUtilities.iterateDomainBounds(mockXYDataset, false);

        assertNull(result);
    }
}
